 private void base(){if(timetableScroll!=null){timetableScrollY=timetableScroll.getScrollY();timetableScroll=null;}if(choiceSheet!=null){choiceSheet.close(false);choiceSheet=null;}pageBack=null;LinearLayout previous=root;showingDetail=false;screen++;pager=null;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0xffe5e7f3,0xffc8d4e5}));FrameLayout stage=new FrameLayout(this);stage.setBackgroundColor(0xffe5e7f3);stage.addView(root,new FrameLayout.LayoutParams(-1,-1));setContentView(stage);if(previous!=null&&android.animation.ValueAnimator.areAnimatorsEnabled()){previous.animate().cancel();stage.getOverlay().add(previous);previous.animate().scaleX(1.04f).scaleY(1.04f).alpha(0f).setDuration(220).setInterpolator(new android.view.animation.AccelerateDecelerateInterpolator()).withEndAction(()->stage.getOverlay().remove(previous)).start();LinearLayout incoming=root;incoming.setScaleX(.94f);incoming.setScaleY(.94f);incoming.setAlpha(0f);incoming.post(()->{if(root!=incoming)return;incoming.animate().scaleX(1f).scaleY(1f).alpha(1f).setDuration(280).setInterpolator(new android.view.animation.DecelerateInterpolator()).start();});}}
 private Calendar date(){Calendar c=Calendar.getInstance(TimeZone.getTimeZone("Asia/Shanghai"));c.set(Calendar.HOUR_OF_DAY,12);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);return c;}
 private Calendar monday(){Calendar c=date();String[] p=term.split("-");c.set(Integer.parseInt(p[0]),Integer.parseInt(p[1])-1,Integer.parseInt(p[2]));return c;}
 private int currentWeek(){return Math.max(1,Math.min(30,(int)((date().getTimeInMillis()-monday().getTimeInMillis())/86400000L/7)+1));}
 private TextView icon(String symbol,String description,Runnable action){TextView t=text(symbol,27,INK);t.setGravity(Gravity.CENTER);t.setContentDescription(description);t.setOnClickListener(v->action.run());t.setFocusable(true);return t;}
 private void changeWeek(int next){if(next<1||next>30)return;if(pager!=null&&pager.isAttachedToWindow()){pager.setCurrentItem(next-1,true);}else{week=next;save();home();}}
