  void open(Spinner choice,String label,String[] values){
   int token=++generation;open=true;selected=choice;panel.animate().cancel();shade.animate().cancel();String heading="选择"+label,currentHint="当前："+values[choice.getSelectedItemPosition()]+" · 点击选项确认";if(!TextUtils.equals(title.getText(),heading))title.setText(heading);if(!TextUtils.equals(hint.getText(),currentHint))hint.setText(currentHint);
   for(int i=0;i<options.length;i++){
    RadioButton option=options[i];option.setVisibility(i<values.length?VISIBLE:GONE);if(i>=values.length)continue;boolean current=i==choice.getSelectedItemPosition();String time=values.length==12?"   "+START_TIMES[i]+"–"+END_TIMES[i]:"";
    String caption=values[i]+time;if(!TextUtils.equals(option.getText(),caption))option.setText(caption);option.setChecked(current);option.setContentDescription(label+"，"+values[i]+time+(current?"，已选中":""));
   }
   root.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);setVisibility(VISIBLE);requestFocus();if(android.os.Build.VERSION.SDK_INT>=28)setAccessibilityPaneTitle("选择"+label);
   panel.setTranslationY(dp(24));shade.setAlpha(0f);
   getViewTreeObserver().addOnPreDrawListener(new ViewTreeObserver.OnPreDrawListener(){public boolean onPreDraw(){getViewTreeObserver().removeOnPreDrawListener(this);if(token!=generation||!open||!isAttachedToWindow())return true;scroll.scrollTo(0,Math.max(0,options[choice.getSelectedItemPosition()].getTop()-dp(60)));if(android.animation.ValueAnimator.areAnimatorsEnabled()){panel.animate().translationY(0).setDuration(180).setInterpolator(new android.view.animation.DecelerateInterpolator()).start();shade.animate().alpha(1f).setDuration(180).start();}else{panel.setTranslationY(0);shade.setAlpha(1f);}return true;}});
  }
  void close(boolean animate){
   open=false;int token=++generation;panel.animate().cancel();shade.animate().cancel();Runnable finish=()->{if(token!=generation)return;setVisibility(INVISIBLE);root.setImportantForAccessibility(formAccessibility);if(selected!=null&&selected.isAttachedToWindow())selected.requestFocus();};
   if(animate&&isAttachedToWindow()&&android.animation.ValueAnimator.areAnimatorsEnabled()){panel.animate().translationY(dp(24)).setDuration(120).withEndAction(finish).start();shade.animate().alpha(0f).setDuration(120).start();}else finish.run();
  }
  @Override protected void onDetachedFromWindow(){generation++;panel.animate().cancel();shade.animate().cancel();super.onDetachedFromWindow();}
