 private Spinner courseChoice(LinearLayout card,String label,String[] values,int selected,String tag){TextView caption=text(label,14,0xff56677e);caption.setPadding(0,dp(14),0,dp(8));card.addView(caption);Spinner choice=new Spinner(this){@Override public boolean performClick(){courseChoicePicker(this,label,values);return true;}};ArrayAdapter<String> adapter=new ArrayAdapter<>(this,R.layout.course_choice,values);choice.setAdapter(adapter);choice.setSelection(selected);choice.setBackground(bg(0xfff0f3fa,12));choice.setContentDescription(label);choice.setTag(tag);card.addView(choice,new LinearLayout.LayoutParams(-1,dp(54)));return choice;}
 private void courseForm(Course initial,int index,Runnable back){String baseline=data;LinearLayout body=secondary(initial==null?"添加课程":"校对课程","分别填写课程信息，再选择具体周次与节次。手动修改保存在本机，重新同步会按学校课表覆盖。",back);LinearLayout info=panel(body);info.addView(text("课程信息",18,INK));EditText name=courseField(info,"课程名称 · 必填",initial==null?"":SchoolParser.clean(initial.name),"例如：数据结构","course-name");EditText teacher=courseField(info,"任课老师",initial==null?"":SchoolParser.clean(initial.teacher),"例如：王老师（选填）","course-teacher");EditText room=courseField(info,"上课教室",initial==null?"":SchoolParser.clean(initial.room),"例如：3-204 / 线上（选填）","course-room");if(initial!=null&&initial.teacher.isEmpty()&&!initial.room.isEmpty()){TextView legacy=text("旧课表的老师可能包含在地点信息中，可在此手动分开填写。",12,0xff56677e);legacy.setPadding(0,dp(12),0,0);info.addView(legacy);}LinearLayout schedule=panel(body);schedule.addView(text("上课安排",18,INK));Spinner day=courseChoice(schedule,"星期",new String[]{"星期一","星期二","星期三","星期四","星期五","星期六","星期日"},initial==null?0:initial.day-1,"course-day");String[] units=new String[12];for(int i=0;i<12;i++)units[i]="第 "+(i+1)+" 节";Spinner start=courseChoice(schedule,"开始节次",units,initial==null?0:initial.start-1,"course-start"),end=courseChoice(schedule,"结束节次",units,initial==null?1:initial.end-1,"course-end");LinearLayout weeks=panel(body);weeks.addView(text("具体周次 · 可多选",18,INK));TextView summary=text("",13,0xff56677e);summary.setTag("course-weeks-summary");summary.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);summary.setPadding(0,dp(12),0,dp(8));weeks.addView(summary);ToggleButton[] selected=new ToggleButton[30];Runnable update=()->{StringBuilder value=new StringBuilder();for(int w=1;w<=30;w++)if(selected[w-1]!=null&&selected[w-1].isChecked()){if(value.length()>0)value.append(",");value.append(w);}summary.setText(value.length()==0?"请选择至少一个教学周":prettyWeeks(new Course(1,1,1,"","",value.toString())));summary.setTextColor(value.length()==0?0xff9a3849:0xff56677e);};LinearLayout quick=new LinearLayout(this);weeks.addView(quick);String[] shortcuts={"全选","单周","双周","清空"};for(int i=0;i<4;i++){final int mode=i;Button button=new Button(this);button.setText(shortcuts[i]);button.setTextSize(12);button.setAllCaps(false);button.setPadding(0,0,0,0);button.setMinWidth(0);button.setTextColor(0xff355db0);button.setBackground(bg(0xffe8effb,10));button.setTag("course-weeks-"+i);button.setOnClickListener(v->{for(int w=1;w<=30;w++)selected[w-1].setChecked(mode==0||(mode==1&&w%2==1)||(mode==2&&w%2==0));update.run();});LinearLayout.LayoutParams qp=new LinearLayout.LayoutParams(0,dp(48),1);if(i>0)qp.leftMargin=dp(6);quick.addView(button,qp);}for(int first=1;first<=30;first+=5){LinearLayout row=new LinearLayout(this);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.topMargin=dp(8);weeks.addView(row,rp);for(int w=first;w<first+5;w++){ToggleButton button=new ToggleButton(this);selected[w-1]=button;button.setTextOn(""+w);button.setTextOff(""+w);button.setTextColor(INK);button.setTextSize(14);button.setMinWidth(0);button.setPadding(0,0,0,0);button.setTag("course-week-"+w);button.setContentDescription("第"+w+"周");button.setBackground(bg(0xfff0f3fa,10));button.setOnCheckedChangeListener((v,on)->{button.setBackground(bg(on?0xff355db0:0xfff0f3fa,10));button.setTextColor(on?Color.WHITE:INK);update.run();});button.setChecked(initial==null?w==week:initial.active(w));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,dp(48),1);if(w>first)bp.leftMargin=dp(6);row.addView(button,bp);}}update.run();TextView error=text("",13,0xff9a3849);error.setTag("course-error");error.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);body.addView(error);Button saveButton=action(body,initial==null?"添加并保存":"保存修改",()->{if(name.getText().toString().trim().isEmpty()){name.setError("请填写课程名称");name.requestFocus();return;}if(end.getSelectedItemPosition()<start.getSelectedItemPosition()){error.setText("结束节次不能早于开始节次");return;}StringBuilder chosen=new StringBuilder();for(int w=1;w<=30;w++)if(selected[w-1].isChecked()){if(chosen.length()>0)chosen.append(",");chosen.append(w);}if(chosen.length()==0){error.setText("请选择至少一个教学周");return;}if(!data.equals(baseline)){error.setText("课表已更新，请返回后重新打开课程");return;}try{Course next=new Course(day.getSelectedItemPosition()+1,start.getSelectedItemPosition()+1,end.getSelectedItemPosition()+1,SchoolParser.clean(name.getText().toString()),SchoolParser.clean(room.getText().toString()),chosen.toString(),SchoolParser.clean(teacher.getText().toString()));Course.parse(next.encode());List<Course> courses=Course.parse(data);if(index<0)courses.add(next);else courses.set(index,next);List<String> rows=new ArrayList<>();for(Course c:courses)rows.add(c.encode());data=String.join("\n",rows);save();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(name.getWindowToken(),0);home();toast(initial==null?"课程已添加":"课程已更新");}catch(Exception e){error.setText("课程未保存："+e.getMessage());}});saveButton.setTag("save-course");body.removeView(saveButton);LinearLayout.LayoutParams footer=new LinearLayout.LayoutParams(-1,dp(52));footer.setMargins(dp(20),dp(8),dp(20),dp(16));root.addView(saveButton,footer);choiceSheet=new CourseChoiceSheet();((FrameLayout)root.getParent()).addView(choiceSheet,new FrameLayout.LayoutParams(-1,-1));}
 private EditText field(String hint,boolean secret){EditText e=new EditText(this);e.setSingleLine();e.setTextSize(16);e.setHint(hint);e.setTextColor(INK);e.setHintTextColor(0xff56677e);e.setPadding(dp(16),0,dp(16),0);e.setBackground(bg(0xfff0f3fa,12));e.setInputType(secret?InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD:InputType.TYPE_CLASS_TEXT);e.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);if(secret)e.setSaveEnabled(false);return e;}
 private void login(){String filledAccount=account!=null&&account.isAttachedToWindow()?account.getText().toString():"",filledPassword=password!=null&&password.isAttachedToWindow()?password.getText().toString():"";if(busy){toast("同步正在进行中");return;}LinearLayout body=secondary("同步课表","连接宿迁学院，导入整学期课程。",()->{if(password!=null)password.getText().clear();home();});LinearLayout card=panel(body);TextView schoolTitle=text("宿迁学院",23,INK);schoolTitle.setTypeface(null,Typeface.BOLD);card.addView(schoolTitle);TextView desc=text("使用学校 VPN / 网上办事大厅账号",13,0xff56677e);desc.setPadding(0,dp(8),0,dp(22));card.addView(desc);card.addView(text("学校账号",13,0xff56677e));account=field("学号 / 学校账号",false);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(54));ap.topMargin=dp(8);card.addView(account,ap);TextView passwordLabel=text("登录密码",13,0xff56677e);passwordLabel.setPadding(0,dp(20),0,dp(8));card.addView(passwordLabel);password=field("请输入密码",true);card.addView(password,new LinearLayout.LayoutParams(-1,dp(54)));account.setText(filledAccount);password.setText(filledPassword);account.setContentDescription("学校账号");password.setContentDescription("学校登录密码");CheckBox show=new CheckBox(this);show.setText("显示密码");show.setTextSize(13);show.setTextColor(0xff56677e);show.setMinHeight(dp(48));show.setButtonTintList(android.content.res.ColorStateList.valueOf(0xff355db0));show.setOnCheckedChangeListener((b,on)->{password.setInputType(InputType.TYPE_CLASS_TEXT|(on?InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD:InputType.TYPE_TEXT_VARIATION_PASSWORD));password.setSelection(password.length());});card.addView(show);
  captchaBox=new LinearLayout(this);captchaBox.setGravity(Gravity.CENTER_VERTICAL);captchaBox.setVisibility(View.GONE);captcha=field("验证码",false);captcha.setContentDescription("学校验证码");captchaImage=new ImageView(this);captchaImage.setContentDescription("点击刷新学校验证码");captchaImage.setFocusable(true);captchaImage.setOnClickListener(v->refreshCaptcha());captchaBox.addView(captcha,new LinearLayout.LayoutParams(0,dp(54),1));LinearLayout.LayoutParams cip=new LinearLayout.LayoutParams(dp(100),dp(54));cip.leftMargin=dp(8);captchaBox.addView(captchaImage,cip);card.addView(captchaBox);
  loginStatus=text("正在连接学校…",13,0xff56677e);loginStatus.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);loginStatus.setPadding(0,dp(14),0,dp(8));card.addView(loginStatus);loginButton=action(card,"登录并同步课表",()->submitLogin());loginButton.setEnabled(false);LinearLayout privacy=panel(body);privacy.addView(text("仅用于学校认证",15,INK));TextView note=text("密码不保存到手机。\n同步失败时会保留原课表，已导入的课程可以离线查看。",13,0xff56677e);note.setLineSpacing(dp(4),1);note.setPadding(0,dp(10),0,0);privacy.addView(note);
  int token=screen;worker.execute(()->{try{school.prepare();if(!school.cachedCourses.isEmpty()){String synced=school.cachedCourses;runOnUiThread(()->{if(screen!=token||isDestroyed())return;data=synced;notes=school.courseNotes;save();home();toast("课表已更新");});return;}byte[] image=school.captchaRequired?school.captcha():null;runOnUiThread(()->{if(screen!=token)return;loginStatus.setText("学校连接正常，请输入账号密码。");loginButton.setEnabled(true);if(image!=null){captchaBox.setVisibility(View.VISIBLE);captchaImage.setImageBitmap(BitmapFactory.decodeByteArray(image,0,image.length));}});}catch(Exception e){runOnUiThread(()->{if(screen!=token)return;loginStatus.setText(e.getMessage());loginStatus.setTextColor(0xffb45266);loginButton.setEnabled(true);loginButton.setText("重新连接");loginButton.setOnClickListener(v->login());});}});
 }
 private void refreshCaptcha(){int token=screen;worker.execute(()->{try{byte[] b=school.captcha();runOnUiThread(()->{if(screen==token)captchaImage.setImageBitmap(BitmapFactory.decodeByteArray(b,0,b.length));});}catch(Exception e){runOnUiThread(()->{if(screen==token)loginStatus.setText("验证码加载失败，请重试。");});}});}
 private void submitLogin(){String user=account.getText().toString().trim(),pass=password.getText().toString(),code=captcha.getText().toString().trim();if(user.isEmpty()){account.setError("请输入学校账号");return;}if(pass.isEmpty()){password.setError("请输入密码");return;}if(school.captchaRequired&&code.isEmpty()){captcha.setError("请输入图片验证码");return;}busy=true;loginButton.setEnabled(false);loginStatus.setText("正在认证并同步课程…");((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(password.getWindowToken(),0);int token=screen;worker.execute(()->{try{String next=school.login(user,pass,code);int count=Course.parse(next).size();if(count==0)throw new IllegalArgumentException("学校未返回课程，已保留原课表。");runOnUiThread(()->{busy=false;if(isDestroyed())return;data=next;notes="已从学校同步 · "+count+"条课程\n"+school.courseNotes;week=currentWeek();save();home();toast("课表同步成功");});}catch(Exception e){runOnUiThread(()->{busy=false;if(screen!=token){toast(e.getMessage());return;}loginButton.setEnabled(true);if(SchoolClient.passwordRejected(e.getMessage())){password.getText().clear();password.setError("密码错误，请重新输入");}loginStatus.setText(e.getMessage());loginStatus.setTextColor(0xffb45266);if(school.captchaRequired){captchaBox.setVisibility(View.VISIBLE);refreshCaptcha();}});}});}
